function setTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('ultimateprTheme',theme);const toggle=$('themeToggle');if(toggle){toggle.textContent=theme==='light'?'☾':'☀';toggle.title='Zmień jasny lub ciemny motyw';toggle.setAttribute('aria-label',toggle.title)}}$('themeToggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='light'?'dark':'light');setTheme(localStorage.getItem('ultimateprTheme')||'dark');
let audioContext=null,lastMessageSound=0,soundEnabled=localStorage.getItem('terminalSound')!=='off',soundVolume=Math.max(0,Math.min(1,Number(localStorage.getItem('terminalVolume')??1)));
function ensureAudio(){if(!soundEnabled)return null;audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext}
function soundTone(freq,delay=0,duration=.12){if(soundVolume<=0)return;const a=ensureAudio();if(!a)return;const start=a.currentTime+delay,o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(.9*soundVolume,start+.015);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g).connect(a.destination);o.start(start);o.stop(start+duration+.02)}
function connectionSound(){[659.25,783.99,987.77].forEach((f,i)=>soundTone(f,i*.17,.13))}
function messageSound(){const now=Date.now();if(now-lastMessageSound<800)return;lastMessageSound=now;soundTone(880,0,.14)}
function updateSoundButton(){const toggle=$('soundToggle');if(!toggle)return;toggle.textContent=soundEnabled?'🔔':'🔕';toggle.title='Powiadomienia dźwiękowe terminala';toggle.setAttribute('aria-label',toggle.title);toggle.classList.toggle('active',soundEnabled);const volume=$('soundVolume');if(volume){volume.value=String(Math.round(soundVolume*100));volume.setAttribute('aria-valuetext',`${Math.round(soundVolume*100)}%`)}}
