function terminalTextFor(s,text){let out='';for(const ch of text){if(s.pendingCR){if(ch==='\n'){out+='\n';s.pendingCR=false;continue}out+='\n';s.pendingCR=false}if(ch==='\r'){s.pendingCR=true}else{out+=ch}}return out}
function appendTo(s,text,direction='rx'){const clean=terminalTextFor(s,text);if(!clean)return;s.buffer+=clean;s.messages??=[];const last=s.messages[s.messages.length-1];if(last&&last.direction===direction)last.text+=clean;else s.messages.push({direction,text:clean});if(s===activeSession)renderConversation(s)}
function packetStatusLabel(m){if(m.status==='sent')return `✓ ACK · paczka ${m.packet}/${m.total}`;if(m.status==='waiting_ack')return `↗ Wysłano · oczekiwanie na ACK · paczka ${m.packet}/${m.total}`;if(m.status==='error')return `✕ Błąd · paczka ${m.packet}/${m.total}${m.error?` · ${m.error}`:''}`;if(m.status==='sending')return `… Wysyłanie · paczka ${m.packet}/${m.total}`;return '… Oczekuje na wysłanie'}
function renderConversation(s){const screen=$('screen');s.messages??=[];screen.innerHTML=s.messages.map(m=>`<div class="message-row ${m.direction} ${m.status==='error'?'failed':''}"><div class="message-bubble">${esc(m.text)}${m.direction==='tx'&&m.status?`<small class="packet-status ${m.status}">${esc(packetStatusLabel(m))}</small>`:''}</div></div>`).join('');screen.scrollTop=screen.scrollHeight}
function historyDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleString()}
function renderHistoryConversation(lines){const items=[];for(const line of lines||[]){if(line.kind){items.push({kind:line.kind,time:line.time});continue}const direction=line.direction||'rx',last=items[items.length-1];if(last&&!last.kind&&last.direction===direction)last.text+=String(line.text||'');else items.push({direction,text:String(line.text||''),time:line.time})}const screen=$('screen');screen.innerHTML=items.map(item=>item.kind?`<div class="history-event ${item.kind}"><span>${item.kind==='connected'?'Połączono':'Rozłączono'} — ${esc(historyDate(item.time))}</span></div>`:`<div class="message-row ${item.direction}"><div class="message-bubble">${esc(item.text)}<time class="message-time">${esc(historyDate(item.time))}</time></div></div>`).join('');screen.scrollTop=screen.scrollHeight}
function updateTxPacket(s,m){
  s.messages??=[];
  const pending=s.messages.findIndex(x=>x.direction==='tx'&&x.txID===m.id&&x.packet===0);
  if(pending>=0)s.messages.splice(pending,1);
  let item=s.messages.find(x=>x.direction==='tx'&&x.txID===m.id&&x.packet===m.packet);
  if(!item){
    item={direction:'tx',txID:m.id,packet:m.packet,total:m.total,text:terminalTextFor(s,m.data||''),status:m.state,error:m.error||''};
    s.messages.push(item);
    const previous=s.messages.filter(x=>x!==item&&x.direction==='tx'&&x.txID===m.id&&x.packet>0&&x.packet<m.packet).sort((a,b)=>a.packet-b.packet);
    if(previous.length){
      item.text=previous.map(x=>x.text).join('')+item.text;
      const merged=new Set(previous);
      s.messages=s.messages.filter(x=>!merged.has(x));
    }
  }else{
    item.total=m.total;
    item.status=m.state;
    item.error=m.error||'';
  }
  if(s===activeSession)renderConversation(s);
}
function setTerminalClearMode(next,key=''){terminalClearMode=next;viewedHistoryKey=key;const button=$('clear'),history=next==='history';button.textContent=history?(uiLanguage==='en'?'Delete conversation from history':'Usuń rozmowę z historii'):(uiLanguage==='en'?'Clear terminal':'Wyczyść terminal');button.classList.toggle('danger-button',history)}
function previewBeacon(entry){terminalViewSeq++;activeSession=null;setTerminalClearMode('preview');document.querySelector('.terminal-panel').classList.remove('history-view');const text=String(entry.beacon||'').replace(/\r\n?/g,'\n');$('screen').innerHTML=text?`<div class="message-row rx"><div class="message-bubble">${esc(text)}</div></div>`:`<div class="message-row rx"><div class="message-bubble">Brak odebranego beaconu tej stacji.</div></div>`;$('sessionLabel').textContent=`Beacon — ${entry.callsign}`;showConnectionStatus(false);syncTerminalControls();renderSessions()}
function append(text,direction='rx'){if(activeSession)appendTo(activeSession,text,direction)}
function stateLabel(name,error='',detail=''){const labels=uiLanguage==='en'?{connecting:'Establishing connection',connected:'Connected',releasing:'Ending connection',disconnected:'Disconnected'}:{connecting:'Nawiązywanie połączenia',connected:'Połączono',releasing:'Kończenie połączenia',disconnected:'Rozłączono'};if(['connecting','awaiting_connection'].includes(name))return detail?`${labels.connecting} ${detail}`:labels.connecting;if(['connected','sending','timer_recovery'].includes(name))return labels.connected;if(name==='awaiting_release')return labels.releasing;return labels.disconnected}
function renderTerminalState(s){const name=s?.state||'idle',error=s?.statusError||'',detail=s?.statusDetail||'';$('terminalState').textContent=stateLabel(name,error,detail);$('terminalStateLED').className=['connected','sending','timer_recovery'].includes(name)?'connected':name==='error'||error?'error':['awaiting_connection','connecting','awaiting_release'].includes(name)?'working':''}
