function renderSessions(){$('sessionTabs').innerHTML=[...sessions.values()].reverse().map(s=>`<div data-session="${s.id}" class="session-tab ${s===activeSession?'active':''} ${s.unread?'unread':''}"><button class="session-select" title="${esc(s.label)}"><i class="${['connected','sending','timer_recovery'].includes(s.state)?'on':['disconnected','offline','error'].includes(s.state)?'off':'wait'}"></i><span>${esc(s.label)}</span></button><button class="session-remove" title="Zamknij sesję" aria-label="Zamknij sesję ${esc(s.label)}">×</button></div>`).join('');$('sessionTabs').querySelectorAll('.session-tab').forEach(tab=>{const s=()=>sessions.get(Number(tab.dataset.session));tab.querySelector('.session-select').onclick=()=>activate(s());tab.querySelector('.session-remove').onclick=e=>{e.stopPropagation();closeSession(s())}})}
