const updateStaleTimeoutMs=10*60*1000;
function updateJobIsStale(job){const updated=Date.parse(job&&job.updated_at||'');return Number.isFinite(updated)&&Date.now()-updated>updateStaleTimeoutMs}
function updateProgressNodes(){return{backdrop:$('updateProgressBackdrop'),stage:$('updateProgressStage'),percent:$('updateProgressPercent'),message:$('updateProgressMessage'),bar:$('updateProgressBar')}}
function showUpdateProgress(show){const n=updateProgressNodes();if(!n.backdrop)return;n.backdrop.hidden=!show}
function renderUpdateProgress(job){const n=updateProgressNodes();if(!n.backdrop)return;const status=String(job&&job.status||'idle');if(status==='idle'){showUpdateProgress(false);return}showUpdateProgress(true);const stage=String(job&&job.stage||'').trim();const msg=String(job&&job.message||'').trim();const progressRaw=String(job&&job.progress||'').trim();const pct=Number.parseInt(progressRaw,10);if(n.stage)n.stage.textContent=stage||'Aktualizacja aplikacji';if(n.percent)n.percent.textContent=Number.isFinite(pct)?`${Math.max(0,Math.min(100,pct))}%`: '…';if(n.message)n.message.textContent=msg||'Trwa aktualizacja, proszę czekać.';if(n.bar)n.bar.style.width=Number.isFinite(pct)?`${Math.max(8,Math.min(100,pct))}%`:'38%'}
async function readUpdateJob(){const r=await fetch('/api/update/status',{cache:'no-store'});if(!r.ok)throw new Error(await r.text());return await r.json()}
function startUpdatePolling(){clearInterval(updatePollTimer);updatePollTimer=setInterval(pollUpdateJob,1000);void pollUpdateJob()}
