async function pollUpdateJob(){try{const job=await readUpdateJob();renderUpdateProgress(job);if(!job||job.status==='idle'){if(updateProgressArmed&&Date.now()-updateProgressStartedAt<30000){showUpdateProgress(true);const n=updateProgressNodes();if(n.stage)n.stage.textContent='Uruchamianie aktualizacji';if(n.percent)n.percent.textContent='…';if(n.message)n.message.textContent='Czekam na start procesu aktualizacji.';if(n.bar)n.bar.style.width='12%';$('updateState').textContent='Aktualizacja uruchomiona. Czekam na uruchomienie procesu w tle…';return}updateProgressArmed=false;return}updateProgressArmed=false;if((job.status==='running'||job.status==='queued')&&updateJobIsStale(job)){showUpdateProgress(false);$('updateState').textContent='Aktualizacja nie odpowiada. Sprawdź logi lub spróbuj ponownie.';clearInterval(updatePollTimer);updatePollTimer=null;return}if(job.status==='running'||job.status==='queued'){const pieces=[];if(job.stage)pieces.push(job.stage);if(job.progress)pieces.push(`${job.progress}%`);$('updateState').textContent=pieces.length?pieces.join(' · '):'Aktualizacja trwa…';if(job.message)$('updateState').textContent+=` — ${job.message}`;return}if(job.status==='success'){showUpdateProgress(false);$('updateState').textContent=job.message||'Aktualizacja zakończona. Trwa restart serwera…';clearInterval(updatePollTimer);updatePollTimer=null;waitForRestart();return}if(job.status==='error'){showUpdateProgress(false);$('updateState').textContent=job.message||'Aktualizacja nie powiodła się.';clearInterval(updatePollTimer);updatePollTimer=null;return}}catch(e){if(updateProgressArmed&&Date.now()-updateProgressStartedAt<30000){showUpdateProgress(true);const n=updateProgressNodes();if(n.stage)n.stage.textContent='Uruchamianie aktualizacji';if(n.percent)n.percent.textContent='…';if(n.message)n.message.textContent='Czekam na odpowiedź procesu aktualizacji.';if(n.bar)n.bar.style.width='12%';$('updateState').textContent='Aktualizacja uruchomiona. Czekam na status…';return}$('updateState').textContent=`Trwa aktualizacja… ${e.message||''}`.trim()}}
