async function refreshHistory(){try{const list=await fetch('/api/history',{cache:'no-store'}).then(r=>r.json());list.forEach(c=>rememberActivity(c.station,c.last_seen));$('historyList').innerHTML=list.length?list.map(c=>{const line=c.lines&&c.lines[0],last=line?.kind?(line.kind==='connected'?'Połączono':'Rozłączono'):(line?.text||'');return `<button class="history-row" data-key="${encodeURIComponent(c.key)}" data-mode="${esc(c.mode)}" data-station="${esc(c.station)}" data-port="${esc(c.port)}" data-digi="${esc(c.digi||'')}" title="Klik: pokaż historię, dwuklik: połącz"><strong>${esc(c.station)}</strong><span class="station-port">${esc(c.mode.toUpperCase())}${c.port?' · '+esc(c.port):''}</span><small><time>${new Date(c.last_seen).toLocaleString()}</time><b>${c.sessions} sesji</b></small><p>${esc(last)}</p></button>`}).join(''):'<p class="empty-list">Brak zapisanych rozmów.</p>';$('historyList').querySelectorAll('button').forEach(b=>{let clickTimer;b.onclick=()=>{clearTimeout(clickTimer);clickTimer=setTimeout(()=>openHistory(decodeURIComponent(b.dataset.key)),240)};b.ondblclick=e=>{e.preventDefault();clearTimeout(clickTimer);if(b.dataset.mode==='tnc')connectRadioStation(b.dataset.station,b.dataset.port,b.dataset.digi);else alert('Ponowne połączenie dwuklikiem jest dostępne dla rozmów radiowych TNC.')}})}catch{}}
async function openHistory(key){const view=++terminalViewSeq;try{const r=await fetch(`/api/history/${encodeURIComponent(key)}`,{cache:'no-store'});if(!r.ok)throw new Error(await r.text());const c=await r.json();if(view!==terminalViewSeq)return;activeSession=null;setTerminalClearMode('history',key);document.querySelector('.terminal-panel').classList.add('history-view');showConnectionStatus(false);renderHistoryConversation(c.lines);$('sessionLabel').textContent=`Historia — ${c.station}`;syncTerminalControls();renderSessions()}catch{}}
const saveConfigOriginal=saveConfig;$('saveConfig').onclick=async()=>{if(configModel){configModel.Application??={};configModel.Application.Language=uiLanguage;localStorage.setItem('ultimateprUILanguage',uiLanguage)}return saveConfigOriginal()};const updateMessageTranslations={'Sprawdzanie podpisu pakietu.':'Verifying package signature.','Pobieranie pakietu.':'Downloading package.','Rozpakowywanie pakietu.':'Extracting package.','Instalowanie aktualizacji.':'Installing update.','Uruchamianie aktualizacji.':'Starting update.','Aktualizacja zakończona. Trwa restart serwera…':'Update completed. Restarting the server…','Aktualizacja nie powiodła się.':'Update failed.','Aktualizacja nie odpowiada. Sprawdź logi lub spróbuj ponownie.':'Update is not responding. Check the logs or try again.','Czekam na start procesu aktualizacji.':'Waiting for the update process to start.','Czekam na uruchomienie procesu aktualizacji w tle…':'Waiting for the background update process to start…'};const translateUpdateMessage=text=>uiLanguage==='en'?(updateMessageTranslations[String(text||'').trim()]||text):text;const readUpdateJobOriginal=readUpdateJob;readUpdateJob=async()=>{const job=await readUpdateJobOriginal();if(job&&job.message)job.message=translateUpdateMessage(job.message);return job};$('chooseRestoreConfig').onclick=()=>$('restoreConfigFile').click();$('restoreConfigFile').onchange=()=>{$('restoreConfigFileName').textContent=$('restoreConfigFile').files[0]?.name||(uiLanguage==='en'?'No file selected.':'Nie wybrano pliku.')};$('restoreConfig').onclick=async()=>{const notice=$('restoreNotice'),file=$('restoreConfigFile').files[0];if(!file){notice.className='config-notice error';notice.textContent=uiLanguage==='en'?'Choose a YAML file.':'Wybierz plik YAML.';return}notice.className='config-notice';notice.textContent=uiLanguage==='en'?'Checking backup…':'Sprawdzanie kopii…';try{const r=await fetch('/api/config/restore',{method:'POST',headers:{'Content-Type':'application/yaml'},body:file});if(!r.ok)throw new Error(await r.text());notice.className='config-notice ok';notice.textContent=uiLanguage==='en'?'Backup restored. UltimatePR is restarting…':'Kopia przywrócona. UltimatePR uruchamia się ponownie…';waitForRestart()}catch(e){notice.className='config-notice error';notice.textContent=e.message}};applyUILanguage(uiLanguage);refreshHistory();setInterval(refreshHistory,3000);setInterval(updateActivityLEDs,30000);
let soundVolumeHideTimer=null;const volumeControlElement=$('soundControl'),volumeInputElement=$('soundVolume');function showSoundVolume(){if(!volumeControlElement)return;clearTimeout(soundVolumeHideTimer);volumeControlElement.classList.add('volume-visible')}function scheduleSoundVolumeHide(){if(!volumeControlElement)return;clearTimeout(soundVolumeHideTimer);soundVolumeHideTimer=setTimeout(()=>{if(!volumeControlElement.matches(':hover')&&!volumeControlElement.matches(':focus-within'))volumeControlElement.classList.remove('volume-visible')},5000)}if(volumeControlElement){volumeControlElement.onpointerenter=showSoundVolume;volumeControlElement.onpointerleave=scheduleSoundVolumeHide;volumeControlElement.onfocusin=showSoundVolume;volumeControlElement.onfocusout=e=>{if(!volumeControlElement.contains(e.relatedTarget))scheduleSoundVolumeHide()}}if(volumeInputElement){volumeInputElement.onpointerenter=showSoundVolume;volumeInputElement.onpointerleave=scheduleSoundVolumeHide}
Object.assign(uiTranslations,{'Oczekiwanie na uruchomienie…':'Waiting to start…','Trwa przygotowanie aktualizacji.':'Preparing update.','Trwa aktualizacja, proszę czekać.':'Update in progress, please wait.','Sprawdzanie…':'Checking…','Aktualizacja trwa…':'Update in progress…','Aktualizacja uruchomiona.':'Update started.','Aktualizacja uruchomiona. Czekam na uruchomienie procesu w tle…':'Update started. Waiting for the background process…','Aktualizacja uruchomiona. Czekam na status…':'Update started. Waiting for status…','Uruchamianie aktualizacji':'Starting update','Czekam na odpowiedź procesu aktualizacji.':'Waiting for the update process to respond.','Zaktualizować UltimatePR z kanału':'Update UltimatePR from channel','Konfiguracja zostanie zachowana.':'Configuration will be preserved.','Nie udało się uruchomić aktualizacji.':'Unable to start the update.','Trwa aktualizacja…':'Update in progress…','Sprawdzanie ustawień…':'Checking settings…','Wersja aktualna':'Version is up to date','Dostępna aktualizacja':'Update available'});const updateTextTranslations={'Sprawdzanie podpisu pakietu.':'Verifying package signature.','Pobieranie pakietu.':'Downloading package.','Rozpakowywanie pakietu.':'Extracting package.','Instalowanie aktualizacji.':'Installing update.','Uruchamianie aktualizacji.':'Starting update.','Uruchamianie aktualizacji…':'Starting update…','Przygotowanie zadania aktualizacji.':'Preparing the update task.','Aktualizacja zakończona. Trwa restart serwera…':'Update completed. Restarting the server…','Aktualizacja nie powiodła się.':'Update failed.','Aktualizacja nie odpowiada. Sprawdź logi lub spróbuj ponownie.':'Update is not responding. Check the logs or try again.','Czekam na start procesu aktualizacji.':'Waiting for the update process to start.','Czekam na uruchomienie procesu aktualizacji w tle…':'Waiting for the background update process to start…','Czekam na odpowiedź procesu aktualizacji.':'Waiting for the update process to respond.','Aktualizacja uruchomiona.':'Update started.','Aktualizacja uruchomiona. Czekam na uruchomienie procesu w tle…':'Update started. Waiting for the background process…','Aktualizacja uruchomiona. Czekam na status…':'Update started. Waiting for status…','Trwa aktualizacja, proszę czekać.':'Update in progress, please wait.','Trwa aktualizacja…':'Update in progress…','Sprawdzanie…':'Checking…','Wersja aktualna':'Version is up to date','Dostępna aktualizacja':'Update available'};const localizeUpdateText=value=>{let text=String(value??'');if(uiLanguage!=='en')return text;Object.entries(updateTextTranslations).sort((a,b)=>b[0].length-a[0].length).forEach(([pl,en])=>{text=text.split(pl).join(en)});return text};const localizeUpdateNodes=()=>['updateState','updateProgressTitle','updateProgressStage','updateProgressMessage'].forEach(id=>{const el=$(id);if(el)el.textContent=localizeUpdateText(el.textContent)});const renderUpdateProgressOriginal=renderUpdateProgress;renderUpdateProgress=job=>{renderUpdateProgressOriginal(job);localizeUpdateNodes()};const pollUpdateJobOriginal= pollUpdateJob;pollUpdateJob=async()=>{await pollUpdateJobOriginal();localizeUpdateNodes()};const checkUpdateOriginal=$('checkUpdate').onclick;$('checkUpdate').onclick=async()=>{await checkUpdateOriginal();localizeUpdateNodes()};const saveUpdateChannelOriginal=$('saveUpdateChannel').onclick;$('saveUpdateChannel').onclick=async()=>{await saveUpdateChannelOriginal();localizeUpdateNodes()};const applyUpdateOriginal=$('applyUpdate').onclick;$('applyUpdate').onclick=async()=>{const originalConfirm=window.confirm;window.confirm=message=>originalConfirm(localizeUpdateText(message));try{return await applyUpdateOriginal()}finally{window.confirm=originalConfirm}};applyUILanguage(uiLanguage);localizeUpdateNodes();
const updateDescriptionElement=document.createElement('p');updateDescriptionElement.id='updateDescription';updateDescriptionElement.className='label-note';const updateHeading=document.querySelector('#updateChannel')?.closest('.settings-card')?.querySelector('h3');if(updateHeading)updateHeading.after(updateDescriptionElement);const updateAvailabilityText=()=>{if(updateDescriptionElement)updateDescriptionElement.textContent=uiLanguage==='en'?'Checking for a new version does not install anything. An update is started only when a newer release is available.':'Sprawdzenie nowej wersji niczego nie instaluje. Aktualizacja uruchamia się tylko wtedy, gdy dostępny jest nowszy release.'};const localizeUpdateNodesEnhanced=()=>{localizeUpdateNodes();const state=$('updateState');if(state&&uiLanguage==='en'&&/^Wersja .+ jest już aktualna\.$/.test(state.textContent))state.textContent='Version '+state.textContent.slice(7,-16)+' is already up to date.';if(state&&uiLanguage==='en'&&/^Wersja .+ jest aktualna\.$/.test(state.textContent))state.textContent='Version '+state.textContent.slice(7,-11)+' is up to date.';updateAvailabilityText()};const updateAvailabilityAfterCheck=async()=>{await checkUpdateOriginal();localizeUpdateNodesEnhanced();const state=$('updateState')?.textContent||'';$('applyUpdate').disabled=state==='Wersja aktualna'||state==='Version is up to date'};$('checkUpdate').onclick=updateAvailabilityAfterCheck;$('updateChannel').addEventListener('change',()=>{$('applyUpdate').disabled=false;updateAvailabilityText()});const applyUpdateWithState=async()=>{try{return await applyUpdateOriginal()}finally{localizeUpdateNodesEnhanced()}};$('applyUpdate').onclick=applyUpdateWithState;updateAvailabilityText();
Object.assign(updateTextTranslations,{'Sprawdzanie dostępnej aktualizacji.':'Checking for an available update.','Pobieranie pakietu aktualizacji.':'Downloading update package.','Rozpakowywanie aktualizacji.':'Extracting update.','Tworzenie kopii poprzedniej wersji.':'Creating a backup of the previous version.','Instalowanie nowej wersji.':'Installing the new version.','Restartowanie usługi systemd.':'Restarting the systemd service.','Restartowanie usługi OpenRC.':'Restarting the OpenRC service.','Aktualizacja UltimatePR zakończona.':'UltimatePR update completed.','Aktualizacja UltimatePR nie powiodła się.':'UltimatePR update failed.','Wersja jest już aktualna.':'The version is already up to date.'});const localizeUpdateNodesFinal=()=>{localizeUpdateNodes();const state=$('updateState');if(state&&uiLanguage==='en'){const current=state.textContent.match(/^Wersja (.+) jest już aktualna\.$/);if(current)state.textContent='Version '+current[1]+' is already up to date.'}updateAvailabilityText()};$('checkUpdate').onclick=async()=>{await checkUpdateOriginal();localizeUpdateNodesFinal();const state=$('updateState')?.textContent||'';$('applyUpdate').disabled=state.includes('is up to date')||state==='Wersja aktualna'};const applyUpdateWithConfirm=async()=>{const originalConfirm=window.confirm;window.confirm=message=>originalConfirm(localizeUpdateText(message));try{return await applyUpdateWithState()}finally{window.confirm=originalConfirm;localizeUpdateNodesFinal()}};$('applyUpdate').onclick=applyUpdateWithConfirm;
const updateUiIsEnglish=()=>document.documentElement.lang==='en'||$('applicationLanguage')?.value==='en';const translateUpdateForCurrentLanguage=value=>{let text=String(value??'');if(!updateUiIsEnglish())return text;Object.entries(updateTextTranslations).sort((a,b)=>b[0].length-a[0].length).forEach(([pl,en])=>{text=text.split(pl).join(en)});return text};const localizeUpdateNodesCurrent=()=>{['updateState','updateProgressTitle','updateProgressStage','updateProgressMessage'].forEach(id=>{const el=$(id);if(el)el.textContent=translateUpdateForCurrentLanguage(el.textContent)});const state=$('updateState');if(state&&updateUiIsEnglish()){const current=state.textContent.match(/^Wersja (.+) jest już aktualna\.$/);if(current)state.textContent='Version '+current[1]+' is already up to date.'}updateAvailabilityText()};const checkUpdateCurrent=async()=>{await checkUpdateOriginal();localizeUpdateNodesCurrent();const state=$('updateState')?.textContent||'';$('applyUpdate').disabled=state.includes('is up to date')||state==='Wersja aktualna'};$('checkUpdate').onclick=checkUpdateCurrent;const applyUpdateCurrent=async()=>{const originalConfirm=window.confirm;window.confirm=message=>originalConfirm(translateUpdateForCurrentLanguage(message));try{return await applyUpdateWithState()}finally{window.confirm=originalConfirm;localizeUpdateNodesCurrent()}};$('applyUpdate').onclick=applyUpdateCurrent;const pollUpdateCurrentOriginal=pollUpdateJob;pollUpdateJob=async()=>{await pollUpdateCurrentOriginal();localizeUpdateNodesCurrent()};const renderUpdateCurrentOriginal=renderUpdateProgress;renderUpdateProgress=job=>{renderUpdateCurrentOriginal(job);localizeUpdateNodesCurrent()};$('applicationLanguage')?.addEventListener('change',updateAvailabilityText);localizeUpdateNodesCurrent();
const checkUpdateImmediate=async()=>{const pending=checkUpdateOriginal();localizeUpdateNodesCurrent();await pending;localizeUpdateNodesCurrent();const state=$('updateState')?.textContent||'';$('applyUpdate').disabled=state.includes('is up to date')||state==='Wersja aktualna'};$('checkUpdate').onclick=checkUpdateImmediate;
const showAppConfirm=message=>new Promise(resolve=>{const backdrop=$('appConfirmBackdrop'),title=$('appConfirmTitle'),body=$('appConfirmMessage'),cancel=$('appConfirmCancel'),ok=$('appConfirmOk');if(!backdrop||!title||!body||!cancel||!ok){resolve(false);return}const english=updateUiIsEnglish();title.textContent=english?'Confirmation':'Potwierdzenie';body.textContent=translateUpdateForCurrentLanguage(message);cancel.textContent=english?'Cancel':'Anuluj';ok.textContent=english?'Confirm':'OK';backdrop.hidden=false;const finish=value=>{backdrop.hidden=true;cancel.onclick=null;ok.onclick=null;backdrop.onclick=null;document.removeEventListener('keydown',onKey);resolve(value)};const onKey=e=>{if(e.key==='Escape')finish(false)};cancel.onclick=()=>finish(false);ok.onclick=()=>finish(true);backdrop.onclick=e=>{if(e.target===backdrop)finish(false)};document.addEventListener('keydown',onKey);ok.focus()});const applyUpdateWithAppConfirm=async()=>{const channel=$('updateChannel')?.value||'main',message=`Zaktualizować UltimatePR z kanału ${channel}? Konfiguracja zostanie zachowana.`;if(!await showAppConfirm(message))return;const originalConfirm=window.confirm;window.confirm=()=>true;try{return await applyUpdateCurrent()}finally{window.confirm=originalConfirm}};$('applyUpdate').onclick=applyUpdateWithAppConfirm;
$('clearHistoryDatabase').onclick=async()=>{if(!await showAppConfirm('Usunąć całą historię rozmów ze wszystkich stacji? Tej operacji nie można cofnąć.'))return;const notice=$('databaseNotice');notice.hidden=false;notice.className='config-notice';notice.textContent=uiLanguage==='en'?'Deleting conversation history…':'Usuwanie historii rozmów…';const r=await fetch('/api/history',{method:'DELETE'});if(!r.ok){notice.className='config-notice error';notice.textContent=await r.text()||'Nie udało się usunąć historii.';return}notice.className='config-notice ok';notice.textContent=uiLanguage==='en'?'All conversation history has been deleted.':'Cała historia rozmów została usunięta.';await refreshHistory();if(terminalClearMode==='history'){const next=sessions.values().next().value;if(next)activate(next);else{setTerminalClearMode('session');$('screen').replaceChildren();$('sessionLabel').textContent=uiLanguage==='en'?'No active session':'Brak aktywnej sesji';document.querySelector('.terminal-panel').classList.remove('history-view')}}};
